  Lemma pd_memset : forall (Q : machine_state -> Prop) R1 m RT SF FT HT (retpc spc : Z),
    rfull R1 -> rtbl Wp R1 RT -> ftbl Wp spz m SF -> ftbl Wp ff m FT -> ftbl Wp (ff / 8) m HT -> Pw m -> mem_inv asegs m ->
    as_RFS H ((2, ff, fp) :: LF) m ->
    PropExec.getr R1 10 = Z_to_bv 64 (ff + 32) -> PropExec.getr R1 11 = Z_to_bv 64 0 -> PropExec.getr R1 12 = Z_to_bv 64 16 ->
    PropExec.getr R1 2 = Z_to_bv 64 spc -> PropExec.getr R1 1 = Z_to_bv 64 retpc ->
    spz - 160 <= spc <= spz - 128 -> 0 <= retpc < 2 ^ 64 -> retpc mod 2 = 0 ->
    forallb (fun j => fent_in (SHBASE + 4 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 2) = true ->
    fin (-8192) 0 (fkeys SF) = true -> fin 0 256 (fkeys FT) = true -> fin SHBASE (SHBASE + 32) (fkeys HT) = true ->
    (forall R2 m2, rfull R2 -> rtbl Wp R2 (LbA_DCtorK.keptf RT) -> ftbl Wp spz m2 (fabove (spc - spz) SF) ->
       ftbl Wp ff m2 (fdrop 32 16 FT ++ zents 32 2) -> ftbl Wp (ff / 8) m2 HT -> Pw m2 -> mem_inv asegs m2 ->
       as_RFS H ((2, ff, fp) :: LF) m2 ->
       evt asegs Q (MS R2 F (Z_to_bv 64 retpc) fc None m2 (seg_rom asegs))) ->
    evt asegs Q (MS R1 F (Z_to_bv 64 AASAN_MEMSET) fc None m (seg_rom asegs)).
Proof.
