  Lemma fr_addr : forall m HT k0, ftbl Wp (ff / 8) m HT ->
    forallb (fun j => fent_in (SHBASE + k0 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
