  Lemma pd_ctor : forall (Q : machine_state -> Prop) R m RT SF FT HT (spc : Z),
    rfull R -> rtbl Wp R RT -> ftbl Wp spz m SF -> ftbl Wp ff m FT -> ftbl Wp (ff / 8) m HT -> Pw m -> mem_inv asegs m ->
    as_RFS H ((2, ff, fp) :: LF) m ->
    PropExec.getr R 10 = Z_to_bv 64 ds -> PropExec.getr R 11 = Z_to_bv 64 (ff + 32) -> PropExec.getr R 12 = Z_to_bv 64 pcons ->
    PropExec.getr R 13 = Z_to_bv 64 (ff + 96) -> PropExec.getr R 14 = Z_to_bv 64 (err mod 2 ^ 64) ->
    PropExec.getr R 15 = Z_to_bv 64 (ff + 160) -> PropExec.getr R 2 = Z_to_bv 64 spc ->
    (spc = spz - 128 \/ spc = spz - 144) ->
    forallb (fun j => fent_in (SHBASE + 32 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
    forallb (fun j => fent_in (SHBASE + 96 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
    forallb (fun j => fent_in (SHBASE + 160 / 8 + Z.of_nat j, 1%nat, ELit 0) HT) (seq 0 (Z.to_nat (24 / 8))) = true ->
    fent_in (32, 8%nat, ELit 0) FT = true -> fent_in (32 + 8, 8%nat, ELit 0) FT = true -> fent_in (32 + 16, 8%nat, EVar 36) FT = true ->
    fent_in (96, 2%nat, ELit 0) FT = true -> fent_in (160, 2%nat, ELit 0) FT = true ->
    fin (-8192) 0 (fkeys SF) = true -> fin 0 256 (fkeys FT) = true -> fin SHBASE (SHBASE + 32) (fkeys HT) = true ->
    (forall R2 m2, rfull R2 -> (forall r, In r KEPT -> PropExec.getr R2 r = PropExec.getr R r) ->
       ftbl Wp spz m2 (fabove (spc - spz) SF) -> ftbl Wp ff m2 FT -> ftbl Wp (ff / 8) m2 HT -> Pw m2 -> mem_inv asegs m2 ->
       as_RFS H ((2, ff, fp) :: LF) m2 -> (forall LB, ds_repA0 LB m2 ds err 0 []) ->
       evt asegs Q (MS R2 F (ret_pc (PropExec.getr R 1)) fc None m2 (seg_rom asegs))) ->
    evt asegs Q (MS R F (Z_to_bv 64 ADS_CTOR) fc None m (seg_rom asegs)).
Proof.
