    PropExec.getr R 24 = s8 -> PropExec.getr R 25 = s9 -> PropExec.getr R 26 = s10 -> PropExec.getr R 27 = s11 ->
    Pw m -> mem_inv asegs m -> ftbl Wp fp m LT -> fent_in (0, 1%nat, ELit 0) LT = true ->
    as_RFS H ((2, ff, fp) :: LF) m4 -> munch (winsT [tS SF ks1; tF FT ks2; tH HT ks3; tL LT0 ks4]) m4 m -> wmono asegs m4 m ->
    (forall LB, ds_repA0 LB m4 ds err 0 []) ->
